# %% ../../nbs/01_datasets.ossl.ipynb #6f0e7d32
class OSSL(GetAttr):
    "OSSL (Open Soil Spectral Library) data container, indexed by sample ID"
    _default = 'df'
    def __init__(
        self,
        df:pd.DataFrame # OSSL data, one row per sample
    ):
        if 'id.layer_uuid_txt' in df.columns: df = df.set_index(pd.Index(df['id.layer_uuid_txt'], name='id'))
        self.df = df
        self._parse_columns()
        self.sample_ids = df.index.to_numpy()

    def __len__(self): return len(self.df)

    def __getitem__(self, k):
        "Columns for a column name or list of names, otherwise a new `OSSL` with the selected samples"
        if isinstance(k, (str, list)): return self.df[k]
        return OSSL(self.df[k])

# %% ../../nbs/01_datasets.ossl.ipynb #2b607e7d
@patch
def _parse_columns(self:OSSL):
    "Parse columns into visnir, mir and properties"
    self.visnir_cols = [c for c in self.df.columns if re.match(r'scan_visnir\.\d+_ref', c)]
    self.mir_cols = [c for c in self.df.columns if re.match(r'scan_mir\.\d+_abs', c)]
    spectral_cols = set(self.visnir_cols + self.mir_cols)
    self.meta_cols = [c for c in self.df.columns if c not in spectral_cols]

# %% ../../nbs/01_datasets.ossl.ipynb #593f3831
def get_cache_path(
    dest_dir:str='.soilspecdata', # Name of the cache directory, relative to the home directory
) -> Path: # Path to the cache directory
    "Get cache path for OSSL data"
    return Path.home()/dest_dir

# %% ../../nbs/01_datasets.ossl.ipynb #fd279b7a
def load_ossl(
    level='L0', # OSSL data level: 'L0' (original lab methods) or 'L1' (lab methods converted to a target method)
    url=None, # OSSL gzipped CSV URL; if None, the whole-database file for `level`
    force_download=False # if True, download even if the file is cached
) -> OSSL:
    "Load OSSL data from the cache, downloading it first if needed"
    assert level in ('L0', 'L1'), f"level must be 'L0' or 'L1', not {level!r}"
    url = url or f'https://storage.googleapis.com/soilspec4gg-public/ossl_all_{level}_v1.2.csv.gz'
    cache_path = get_cache_path()/Path(urlparse(url).path).name
    if not cache_path.exists() or force_download:
        cache_path.parent.mkdir(exist_ok=True)
        urlretrieve(url, cache_path)
    return OSSL(pd.read_csv(cache_path, compression='gzip', low_memory=False))

# %% ../../nbs/01_datasets.ossl.ipynb #93985934
@patch
def _get_valid_spectra_mask(
    self:OSSL,
    spectra_cols:List[str] # Spectra column names
) -> pd.Series: # True for samples with a value in every column of `spectra_cols`
    "Mask of the samples with complete spectra in `spectra_cols`"
    return self.df[spectra_cols].notna().all(axis=1)

# %% ../../nbs/01_datasets.ossl.ipynb #939eed5a
@patch
def _extract_wavenumbers(
    self:OSSL,
    cols:List[str] # Spectral column names
) -> np.ndarray: # Wavenumbers in cm⁻¹
    "Wavenumbers of spectral columns, converting VISNIR wavelengths in nm to wavenumbers"
    ws = np.array([int(re.search(r'\.(\d+)_', c).group(1)) for c in cols])
    return np.round(1e7/ws).astype(int) if 'visnir' in cols[0] else ws

# %% ../../nbs/01_datasets.ossl.ipynb #e4cc1b8e
@patch
def _extract_measurement_type(
    self:OSSL,
    cols:List[str] # Spectral column names
) -> str: # `abs` (absorbance) or `ref` (reflectance)
    "Extract measurement type from column names"
    types = set(re.search(r'_(\w+)$', c).group(1) for c in cols)
    assert len(types) == 1, f"Mixed measurement types found: {types}"
    return types.pop()

# %% ../../nbs/01_datasets.ossl.ipynb #90f8fe64
@patch
def _filter_wavenumbers(
    self:OSSL,
    wavenumbers:np.ndarray, # Wavenumbers of `cols`
    cols:List[str], # Spectral column names
    wmin:Optional[int]=None, # Min wavenumber; the smallest in `wavenumbers` if None
    wmax:Optional[int]=None # Max wavenumber; the largest in `wavenumbers` if None
) -> Tuple[np.ndarray, List[str]]: # Wavenumbers and column names within the range
    "Wavenumbers and columns between `wmin` and `wmax`, inclusive"
    lo, hi = wavenumbers.min(), wavenumbers.max()
    if wmin is None: wmin = lo
    if wmax is None: wmax = hi
    assert lo <= wmin < wmax <= hi, f"Need {lo} <= wmin < wmax <= {hi}, got wmin={wmin}, wmax={wmax}"
    mask = (wavenumbers >= wmin) & (wavenumbers <= wmax)
    return wavenumbers[mask], [c for c, m in zip(cols, mask) if m]

# %% ../../nbs/01_datasets.ossl.ipynb #b71c71a5
@patch
def _get_spectra(
    self:OSSL,
    cols:List[str], # Spectral column names
    wmin:Optional[int]=None, # Min wavenumber
    wmax:Optional[int]=None # Max wavenumber
) -> Spectra: # Complete spectra, in increasing wavenumber order
    "Complete spectra of the columns in `cols` between `wmin` and `wmax`, sorted by wavenumber"
    wavenumbers, cols = self._filter_wavenumbers(self._extract_wavenumbers(cols), cols, wmin, wmax)
    order = np.argsort(wavenumbers)
    cols = [cols[i] for i in order]
    mask = self._get_valid_spectra_mask(cols).to_numpy()
    return Spectra(wavenumbers[order], self.df.loc[mask, cols].to_numpy(),
        self._extract_measurement_type(cols), self.sample_ids[mask], source=self)

# %% ../../nbs/01_datasets.ossl.ipynb #f59cc524
@patch
def visnir(
    self:OSSL,
    wmin:Optional[int]=4000, # Min wavenumber
    wmax:Optional[int]=25000 # Max wavenumber
) -> Spectra: # VISNIR spectra, in increasing wavenumber order
    "Complete VISNIR spectra between `wmin` and `wmax`"
    return self._get_spectra(self.visnir_cols, wmin, wmax)

# %% ../../nbs/01_datasets.ossl.ipynb #f5f88422
@patch
def mir(
    self:OSSL,
    wmin:Optional[int]=600, # Min wavenumber
    wmax:Optional[int]=4000 # Max wavenumber
) -> Spectra: # MIR spectra, in increasing wavenumber order
    "Complete MIR spectra between `wmin` and `wmax`"
    return self._get_spectra(self.mir_cols, wmin, wmax)

# %% ../../nbs/01_datasets.ossl.ipynb #be231f89
@patch
def xy(
    self:Spectra,
    target_cols:Union[str, List] # Target column name or names
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]: # Spectra, targets and sample IDs, row by row
    "Spectra and targets of the samples that have both, for machine learning"
    targets = self.source[listify(target_cols)].dropna()
    aligned = pd.DataFrame(self.spectra, index=self.sample_ids).join(targets, how='inner')
    n = self.spectra.shape[1]
    return aligned.iloc[:, :n].to_numpy(), aligned.iloc[:, n:].to_numpy(), aligned.index.to_numpy()

