def _warn_deprecated(old, new):
    "Warn the caller of a deprecated function `old` to use `new`"
    warnings.warn(f"`{old}` is deprecated and will be removed in the next release; use `{new}`", DeprecationWarning, stacklevel=3)

def _deprecated(f, old):
    "Wrap `f` to warn that `old` is its deprecated name"
    def _f(*args, **kwargs):
        _warn_deprecated(old, f.__name__)
        return f(*args, **kwargs)
    return _f

